    final browserSlideCtrl = useAnimationController(
      duration: const Duration(milliseconds: 280),
    );
    final browserSlideT = useMemoized(
      () =>
          CurvedAnimation(parent: browserSlideCtrl, curve: Curves.easeOutCubic),
